<?php $title='Dashboard';require 'includes/header.php';$stats=['Products'=>$pdo->query("SELECT COUNT(*) FROM products")->fetchColumn(),'Categories'=>$pdo->query("SELECT COUNT(*) FROM categories")->fetchColumn(),'Enquiries'=>$pdo->query("SELECT COUNT(*) FROM enquiries")->fetchColumn(),'New Enquiries'=>$pdo->query("SELECT COUNT(*) FROM enquiries WHERE status='New'")->fetchColumn(),'Offers'=>$pdo->query("SELECT COUNT(*) FROM offers")->fetchColumn(),'Messages'=>$pdo->query("SELECT COUNT(*) FROM contact_messages")->fetchColumn()];?><h1 class="mb-4">Dashboard</h1><div class="row g-3"><?php foreach($stats as $k=>$v):?><div class="col-sm-6 col-lg-4"><div class="card stat shadow-sm p-4"><div class="text-muted"><?=e($k)?></div><div class="display-6 fw-bold"><?=$v?></div></div></div><?php endforeach;?></div><?php require 'includes/footer.php';?>